function validarCorreo(t){return/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(t)}function soloLetras(t){return/^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$/.test(t)}function validarLongitud(t,e){return t.toString().length<=e}function calcularEdad(t){const e=new Date,r=new Date(t);let n=e.getFullYear()-r.getFullYear();const a=e.getMonth()-r.getMonth();return(a<0||0===a&&e.getDate()<r.getDate())&&n--,n}function esMayorDeEdad(t){return calcularEdad(t)>=18}function validarPassword(t){return/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[\W_]).{8,}$/.test(t)}function limpiarEspacios(t){return t.trim().replace(/\s+/g," ")}function esEsPar(t){return Number.isInteger(t)&&t%2==0}